      en: ["Built in 1900.", "Upon completion, it was the largest railway trestle in the world.", "The bridge is 689 meters long."],
      es: ["Construido en el año 1900.", "Fue el caballete ferroviario más grande del mundo al terminarse.", "El puente tiene 689 metros de largo."],
      pt: ["Construído no ano de 1900.", "Era o maior cavalete ferroviário do mundo aquando da sua conclusão.", "A ponte tem 689 metros de comprimento."],
