      en: "Myanmar's most famous beach, renowned for its pristine white sand and the crystal clear waters of the Bay of Bengal.",
      es: "La playa más famosa de Myanmar, conocida por su arena blanca virgen y las aguas cristalinas del golfo de Bengala.",
      pt: "A praia mais famosa de Myanmar, famosa pela sua areia branca imaculada e pelas águas cristalinas do Golfo de Bengala.",
