      ro: ["Înălțimea totală a cascadei este de 120 de metri.", "Drumul de întoarcere (urcușul) durează circa o oră.", "Este situată în apropierea satului Anisakan.", "Găzduiește o mică pagodă aurie chiar la baza apei.", "Debitul maxim este atins între lunile iulie și octombrie.", "Apa provine din râul Dattawgyaik de pe platoul Shan."],
      en: ["The waterfall has a total drop of about 120 meters.", "The hike down to the base takes roughly 45 minutes.", "Located near Anisakan village, close to Pyin Oo Lwin.", "Features a small golden pagoda at the very bottom.", "Most spectacular during the rainy season (July-October).", "Part of the Dattawgyaik River system on the Shan Plateau."],
      es: ["La cascada tiene una altura de unos 50 metros.", "La piscina tiene hasta 5 metros de profundidad.", "La distancia desde Hpa-an es de 7 kilómetros.", "El caudal en la estación de lluvias es de 20 m³/s.", "La cascada se encuentra a 200 metros sobre el nivel del mar.", "Cada año visitan la cascada 80.000 personas."],
      pt: ["A cachoeira tem uma altura de cerca de 50 metros.", "A piscina tem até 5 metros de profundidade.", "A distância de Hpa-an é de 7 quilómetros.", "O caudal na estação das chuvas é de 20 m³/s.", "A cachoeira situa-se a 200 metros acima do nível do mar.", "Anualmente, 80.000 pessoas visitam a cachoeira."],
      fr: ["La cascade a une hauteur d'environ 50 mètres.", "Le bassin a une profondeur allant jusqu'à 5 mètres.", "La distance depuis Hpa-an est de 7 kilomètres.", "Le débit en saison des pluies est de 20 m³/s.", "La cascade est située à 200 mètres au-dessus du niveau de la mer.", "Chaque année, 80 000 personnes visitent la cascade."],
